function setup() {
	createCanvas(600, 600);
	background("beige")
	rectMode(CENTER)
	noStroke()
}

function draw() {
	const t = width / 4;
	patternColors([color(0), color(0, 0, 240),color(200)]);


	const num = 8;
	const S = width/(num*2+1);
	translate(width/2 + S/2, height/2 + S/2)
	for (let y = -num; y < num; y++) {		
		for (let x = -num; x < num; x++) {
			const tpe = ~~random(4)
			if (tpe < 8) {
				push()				
				translate(x*S, y*S)
				fill(random(["orange", "grey", "darkred", "black"]))
				// fill(32)

				if (tpe === 0) circle(0, 0, S * 0.73);
				if (tpe === 1) rect(0, 0, S * 0.43, S * 0.1);
				if (tpe === 2) rect(0, 0, S * 0.43);

				pop()
			}
		}
	}
	// noLoop() removed for animation
}



